{"@context": "https://schema.org", "@type": "DefinedTermSet", "name": "Термины: казначейское сопровождение для бухгалтера", "inLanguage": "ru-RU", "hasDefinedTerm": [{"@type": "DefinedTerm", "name": "Казначейское сопровождение", "description": "Режим контроля целевых средств по главе 24.4 Бюджетного кодекса: деньги контракта зачисляются на лицевой счёт в казначействе, платежи проходят санкционирование."}, {"@type": "DefinedTerm", "name": "Раздельный учёт", "description": "Обособленный учёт доходов, расходов, активов и обязательств по каждому сопровождаемому контракту; с 2026 года его отсутствие — состав по ст. 15.37.1 КоАП."}, {"@type": "DefinedTerm", "name": "Код направления расходования", "description": "Укрупнённый код из приложения 3 к приказу № 214н, которым маркируется каждый платёж с лицевого счёта; первый разряд обозначает механизм операции."}, {"@type": "DefinedTerm", "name": "Сведения об операциях с целевыми средствами", "description": "Плановый документ по форме 0501213 со структурой расходов контракта; утверждается заказчиком, платежи проходят только в его рамках."}, {"@type": "DefinedTerm", "name": "Распоряжение о совершении казначейского платежа", "description": "Платёжный документ казначейского контура; подаётся с документами-основаниями и проверяется при санкционировании."}, {"@type": "DefinedTerm", "name": "Санкционирование", "description": "Проверка казначейством распоряжения и документов перед списанием средств с лицевого счёта; порядок — приказ Минфина № 214н, по общему правилу до двух рабочих дней."}, {"@type": "DefinedTerm", "name": "Отчёт о расходах целевых средств", "description": "Фактический отчёт об использовании средств контракта; сверяется с выпиской и регистрами раздельного учёта."}, {"@type": "DefinedTerm", "name": "Выписка из лицевого счёта", "description": "Ежедневный документ казначейства об операциях и остатках по лицевому счёту; основа сверки с бухгалтерским учётом."}]}
